import numpy as np
from scipy import stats

MAX_DRIVERS = 5

def design(feats):
    # Find features with significant association (p < 0.05)
    sig_features = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] != 'derived':
            t_stat, p_val = stats.ttest_ind(feats.x[feats.y==1, i], feats.x[feats.y==0, i])
            if p_val < 0.05:
                sig_features.append((fid, abs(t_stat)))

    # Sort by effect size
    sig_features.sort(key=lambda x: x[1], reverse=True)

    # Check for near-duplicates (correlated pairs with |r| >= 0.6)
    correlated_pairs = set()
    for i in range(len(feats.ids)):
        for j in range(i+1, len(feats.ids)):
            r = np.corrcoef(feats.x[:,i], feats.x[:,j])[0,1]
            if abs(r) >= 0.6:
                fid1, fid2 = feats.ids[i], feats.ids[j]
                # Add pair in sorted order to avoid duplicates
                pair = tuple(sorted([fid1, fid2]))
                correlated_pairs.add(pair)

    # Select top features avoiding near-duplicates
    selected = []
    used = set()
    for fid, _ in sig_features:
        # Skip if already included via correlation
        if any(fid in pair for pair in correlated_pairs if pair[0] in used or pair[1] in used):
            continue
        selected.append(fid)
        used.add(fid)
        if len(selected) >= MAX_DRIVERS:
            break

    # Look for interaction terms among top features
    products = []
    if len(selected) >= 2:
        # Try pairwise products
        for i in range(min(3, len(selected))):
            for j in range(i+1, min(3, len(selected))):
                fid1, fid2 = selected[i], selected[j]
                products.append((fid1, fid2))

    # For this world, we have strong evidence for HOB18 as primary driver
    # and several correlated features suggesting potential interactions
    drivers = ('HOB18',) if selected else ()
    columns = selected
    return Design(drivers=drivers, columns=columns, products=products, loadings={})

class Design:
    def __init__(self, drivers, columns, products, loadings):
        self.drivers = drivers
        self.columns = columns
        self.products = products
        self.loadings = loadings
